import React, { Component } from 'react';
import classes from './Forms.module.css';
import { ipfs } from '../../../../ipfs';
import { ipfsCluster } from '../../../../ipfs';
import Input from '../../../../components/UI/Input/Input';
import Spinner from '../../../../components/UI/Spinner/Spinner';
import SpinnerModal from '../../../../components/UI/SpinnerModal/SpinnerModal';
import Button from '../../../../components/UI/Button/Button';
import axios from '../../../../axios-orders';
import { NavLink } from 'react-router-dom';
import CryptoJS from "crypto-js";
import bs58 from 'bs58';
var str2ab = require('string-to-arraybuffer');


// WebWorker helper class
//import MyWorker from './MySomething.worker';
//import WebWorker from './workerHelper';
// Your web worker


class Forms extends Component {

    state = {
        buffer: null,
        genomics: false,
        dicom: false,
        initial: true,
        displayForm: false,
        individual: false,
        ipfsHash:  null,
        uploadedData: true,
        seed: null,
        seedConfirmed: false,
        iv: null,
        encryptedData: null,
        idHashArray: [{}],
        idChunkArray: null,
        finalRead: false,
        encrypting: false,
        filesize: null,
        hashesArray: null,
        msg: ["Loading and encrypting your file. Please wait..", "Sending your file to IPFS. Please wait.."],

        searchFormGenomics: {
            Address: {
                elementType: 'input-address',
                value: this.props.accounts[0]
            },
            Age: {
                elementType: 'input',
                elementConfig: {
                    type: 'text',
                    placeholder: 'Type your age...'
                },
                value: ''
            },
            Country: {
                elementType: 'input',
                elementConfig: {
                    type: 'text',
                    placeholder: 'Birth place...'
                },
                value: ''
            },
            Data: {
                elementType: 'select',
                elementConfig: {
                    placeholder: 'Select the type of data...',
                    options: [
                        {value: 'BAM-FILE', displayValue: 'BAM-FILE'},
                        {value: 'VCF', displayValue: 'VCF'}
                    ]
                },
                value: ''
            },
            Gender: {
                elementType: 'select',
                elementConfig: {
                    options: [
                        {value: 'Male', displayValue: 'Male'},
                        {value: 'Female', displayValue: 'Female'}
                    ]
                },
                value: ''
            },
            Price: {
                elementType: 'input',
                elementConfig: {
                    type: 'text',
                    placeholder: 'Select a price for the dataset...'
                },
                value: ''
            },
        },

        searchFormDICOM: {
            Address: {
                elementType: 'input-address',
                value: this.props.accounts[0]
            },
            Data: {
                elementType: 'select',
                elementConfig: {
                    options: [
                        {value: 'XR', displayValue: 'XR'},
                        {value: 'PET', displayValue: 'PET'}
                    ]
                },
                value: ''
            },
            Instrument: {
                elementType: 'select',
                elementConfig: {
                    options: [
                        {value: 'Shimadzu', displayValue: 'Shimadzu'},
                        {value: 'LG Biocare', displayValue: 'LG Biocare'}
                    ]
                },
                value: ''
            },
            Region: {
                elementType: 'select',
                elementConfig: {
                    options: [
                        {value: 'Leg', displayValue: 'Leg'},
                        {value: 'Pancreas', displayValue: 'Pancreas'}
                    ]
                },
                value: ''
            },
            Resolution: {
                elementType: 'input',
                elementConfig: {
                    type: 'text',
                    placeholder: 'Choose a resolution (A)....'
                },
                value: ''
            },
            Price: {
                elementType: 'input',
                elementConfig: {
                    type: 'text',
                    placeholder: 'Select a price for the dataset...'
                },
                value: ''
            },
        }
    }

    componentDidUpdate = async () => {
        if (!this.state.uploadedData) {

            let aux = null;
            const formData = {};

            if (this.state.dicom) {
                aux = { ...this.state.searchFormDICOM }
                for (let formElementIdentifier in aux) {
                    formData[formElementIdentifier] = aux[formElementIdentifier].value;
                }
                formData["id"] = this.state.ipfsHash;
            }

            if (this.state.genomics) {
                aux = { ...this.state.searchFormGenomics }
                for (let formElementIdentifier in aux) {
                    formData[formElementIdentifier] = aux[formElementIdentifier].value;
                }
                formData["id"] = this.state.ipfsHash;
            }

            // Upload data to the contract: registerDataset.

            await this.props.contract.registerDataset(this.state.ipfsHash, Math.pow(10, 18) * formData["Price"], { from: this.props.accounts[0] })
                .then(console.log("dataset id (ipfs) registered into the blockchain"));
            // Upload data to the indexation DB.
            axios.post(".json", formData);
            this.setState({ uploadedData: true,
                            seed: null,
                            submitSeed: false });

            alert("Dataset uploaded");
        }
    }

    displayFormGenomicsHandler = (event) => {
        this.setState({ displayForm :  true, 
                        genomics: true,
                        dicom: false });
    }

    displayFormDICOMHandler = (event) => {
        this.setState({ displayForm :  true, 
                        dicom: true,
                        genomics: false });
    }

    hideBoxGenomicsHandler = (event) => {
        if(this.state.genomics) {
            this.setState({ displayForm: false});
        }
    }

    hideBoxDICOMHandler = (event) => {
        if(this.state.dicom) {
            this.setState({ displayForm: false});
        }
    }

    inputChangedHandler = (event, inputIdentifier) => {
        let updatedSearchForm = null;

        if(this.state.genomics) {
            updatedSearchForm = { ...this.state.searchFormGenomics }
        };

        if(this.state.dicom) {
            updatedSearchForm = { ...this.state.searchFormDICOM }
        };

        const updatedSearchElement = { 
            ...updatedSearchForm[inputIdentifier]
        };

        updatedSearchElement.value = event.target.value;
        updatedSearchForm[inputIdentifier] = updatedSearchElement;

        if(this.state.genomics) {
            this.setState({searchFormGenomics: updatedSearchForm});
        };

        if(this.state.dicom) {
            this.setState({searchFormDICOM: updatedSearchForm});
        };
    }

    clearFormHandler = (event) => {
        let updatedSearchForm = null;

        if(this.state.genomics) {
            updatedSearchForm = { ...this.state.searchFormGenomics }
        };

        if(this.state.dicom) {
            updatedSearchForm = { ...this.state.searchFormDICOM }
        };

        const initialSearchForm = {};

        for(let key in updatedSearchForm) {
                initialSearchForm[key] = { ...updatedSearchForm[key] }
                initialSearchForm[key].value = "";
        }

        if(this.state.genomics) {
            this.setState({searchFormGenomics: initialSearchForm});
        };

        if(this.state.dicom) {
            this.setState({searchFormDICOM: initialSearchForm});
        };

    }

    seedHandler = (event) => {
        const dummyPwd = event.target.value;
        this.setState({ seed : dummyPwd })
    }

    submitSeed = (event) => {
        if(this.state.seed) {
            this.setState({ seedConfirmed : true })
        }
    }

    getFileHandler = (event) => {
        // We first capture the file name.
        let file = event.target.files[0];
        // 1) Encryptor generation.

        // KEY and IV creation:

        let iv = window.crypto.getRandomValues(new Uint8Array(16));
        console.log(iv);
        let hexiv = Buffer.from(iv).toString('hex');
        console.log(hexiv);
        let hexiv2 = CryptoJS.enc.Hex.parse(hexiv);
        console.log(hexiv2);
        let hexiv3 = new Uint8Array(Buffer(hexiv2));
        console.log(hexiv3);

        let finalKey = null;

        let validkey = null;
        window.crypto.subtle.generateKey(
            {
                name: "AES-CBC",
                length: 256, //can be  128, 192, or 256
            },
            true, //whether the key is extractable (i.e. can be used in exportKey)
            ["encrypt", "decrypt"] //can be "encrypt", "decrypt", "wrapKey", or "unwrapKey"
        )
        .then(function(key){
            //returns a key object
            validkey = key;
            console.log(validkey);
            window.crypto.subtle.exportKey(
                "jwk", //can be "jwk" or "raw"
                validkey //extractable must be true
            )
            .then(function(keydata){
                //returns the exported key data
                console.log(keydata);
                console.log(keydata.k);
                finalKey = keydata.k;
            })
            .catch(function(err){
                console.error(err);
            });
        })
        .catch(function(err){
            console.error(err);
        });

        /*window.crypto.subtle.exportKey(
            "jwk", //can be "jwk" or "raw"
            validkey //extractable must be true
        )
        .then(function(keydata){
            //returns the exported key data
            console.log(keydata);
        })
        .catch(function(err){
            console.error(err);
        });*/

        //let iv = CryptoJS.lib.WordArray.random(128 / 8);

        // ***** IV should be hexiv and not a wordarray -> Pending revision.
        //let aesEncryptor = CryptoJS.algo.AES.createEncryptor(finalKey, { iv: iv });
        let mierda_encrypt ="";

        // Move it after the dir creation completion ....
        this.setState({ iv: iv, key: finalKey });
        // Worker initialisation
        //const workerInstance = new WebWorker(MyWorker);
        //const workerInstanceWithParams = new WebWorker(new MyWorker(CryptoJS));
        //console.log(workerInstanceWithParams);
        // Communication with worker
        //workerInstanceWithParams.addEventListener("message", e => console.log(e.data), false);
        //workerInstanceWithParams.postMessage("CryptoJS");
        /*var myWorker = new Worker(worker_script);

        myWorker.onmessage = (m) => {
        console.log("msg from worker: ", m.data);
        };
        myWorker.postMessage('im from main');*/

        this.setState({ file: file });
    }

    ipfsUploading = (event) => {

        // 1) Encryptor generation.

        // KEY and IV creation:
        var salt = CryptoJS.lib.WordArray.random(128 / 8);

        var key256Bits = CryptoJS.PBKDF2(this.state.seed,
            salt,
            { keySize: 256 / 32, iterations: 1000 });

        console.log("key256bits: ", key256Bits);
        let hexKey = key256Bits.toString();
        let finalKey = CryptoJS.enc.Hex.parse(hexKey);
        let iv = window.crypto.getRandomValues(new Uint8Array(16));
        let validkey = null;
        window.crypto.subtle.generateKey(
            {
                name: "AES-CBC",
                length: 256, //can be  128, 192, or 256
            },
            false, //whether the key is extractable (i.e. can be used in exportKey)
            ["encrypt", "decrypt"] //can be "encrypt", "decrypt", "wrapKey", or "unwrapKey"
        )
        .then(function(key){
            //returns a key object
            validkey = key;
        })
        .catch(function(err){
            console.error(err);
        });
        //let iv = CryptoJS.lib.WordArray.random(128 / 8);
        let hexiv = iv.toString();


        // ***** IV should be hexiv and not a wordarray -> Pending revision.
        //let aesEncryptor = CryptoJS.algo.AES.createEncryptor(finalKey, { iv: iv });
        let mierda_encrypt ="";

        // Move it after the dir creation completion ....
        this.setState({ iv: hexiv, key: hexKey });

        // 2) Read the file asynchronously and upload the chunks into IPFS (streaming).

        // We first capture the file name and initialize chunk variables. Adjustable -> Chunksize.
        let chunksize = 10000000; // 10 MB
        let threshold = 0;
        let mb = 0;

        // Depending on the file size we will split it in chunks for the IPFS uploading.

        // Abritrary: ***** PENDING FOR REVISION.

        // File size: < 100 MB
        if (this.state.file.size < 100000000) {
            threshold = Math.ceil(this.state.file.size / chunksize);
        }

        // File size:  100 MB < x < 500 MB
        else if ((this.state.file.size > 100000000) && (this.state.file.size < 500000000)) {
            mb = this.state.file.size / 5;
            threshold = Math.ceil(mb / chunksize);
        } 

        else if ((this.state.file.size > 500000000) && (this.state.file.size < 1000000000)) {
            mb = this.state.file.size / 10;
            threshold = Math.ceil(mb / chunksize);
        } 

        else if ((this.state.file.size > 1000000000) && (this.state.file.size < 2000000000)) {
            mb = this.state.file.size / 20;
            threshold = Math.ceil(mb / chunksize);
        } 

        else if ((this.state.file.size > 2000000000) && (this.state.file.size < 3000000000)) {
            mb = this.state.file.size / 40;
            threshold = Math.ceil(mb / chunksize);
        } 

        else if ((this.state.file.size > 3000000000) && (this.state.file.size < 4000000000)) {
            mb = this.state.file.size / 160;
            threshold = Math.ceil(mb / chunksize);
        } 

        else {
            mb = this.state.file.size / 999;
            threshold = Math.ceil(mb / chunksize);
        }

        // Initialize the IPFS hashes array. We store individual chunk hashes for reorganizing them in a directory.
        let arrLen = Math.ceil(this.state.file.size / (threshold * chunksize))
        let newArr = new Array(arrLen).fill(0);
        console.log("arr len: ", newArr);

        /*let worker = new Worker('workerfile.js');

        worker.addEventListener('message', function(e) {
          console.log('Message from Worker: ' + e.data);
        }

        worker.postMessage('Hello World');*/

        // 2.1) Functions declaration.

        // A) Create an IPFS directory: ***** THIS FUNCTION COULD BE A COMPONENT: PROPS: HASHESARRAY & ARRAY

        function createIpfsDirectory(event) {

            // We create an empty directory.
            let dirHash = "QmUNLLsPACCz1vLxQVkXqqLX5R1X345qqfHbsf67hvA3Nn";

            let count = 0;

            let array = [...this.state.hashesArray];
            for (let i = 0; i < array.length - 1; i++) {
                if (array[i] === 0) {
                    array.splice(i, 1);
                }
            }

            const mergeFiles = async (dirHash, limit) => {
                if (count !== limit) {
                    count += 1;
                    let i = count - 1;

                    ipfs.object.patch.addLink(dirHash, {
                        name: array[i].path,
                        size: 37,
                        cid: array[i].hash
                    }, (err, cid) => {
                        if (err) {
                            throw err
                        }
                        dirHash = bs58.encode(cid.multihash);
                        mergeFiles(dirHash, limit);
                    })
                } else {
                    console.log("dirHash: ", dirHash);

                    // ***** WE COULD MOVE THIS INTO THE COMPONENTDIDUPDATE COMPONENT.
                    ipfsCluster.pin.add(dirHash, (err) => {
                        if (err) {
                            throw err
                        };
                        console.log("Pin request succesful!");
                    });

                    let id32bytes = "0x" + bs58.decode(dirHash).slice(2).toString('hex');

                    // ONCE THE DIRECTORY IS CREATED WE REGISTER THE IPFS HASH ENABLING THE UPDATING (UPLOADEDDATA)
                    // IN THE COMPONENTDIDUPDATE LIFECYCLE COMPONENT.
                    this.setState({
                        ipfsHash: id32bytes,
                        uploadedData: false
                    });
                }
            }

            mergeFiles(dirHash, array.length);
        }

        // B) READING-ENCRYPTING-STREAMING FILES: 

        // Parameters declaration.

        let self = this;
        let counter = 0;
        let counterB = 0;
        let counterC = 0;
        let parts = [];
        let previous = [];
        let lastOffset = 0;
        let dataencrypted = "";
        let datadecrypted = "";
        let okpost = 0;
        let databuf = "";
        // Loading closure declaration: Associated functions -> callbackRead && callbackProgress && callbackFinal.
        // ipfsUploading context (self) --> Needed for the global state update after uploading the file. 
        function loading(self, file, callbackProgress, callbackFinal) {
            let offset = 0;
            let size = chunksize;
            let partial;
            let index = 0;


